from datetime import datetime, time


class Notifier:
    CHANNELS = ("email", "sms", "push")

    def __init__(self, quiet_start: time = time(22, 0), quiet_end: time = time(7, 0)) -> None:
        self.quiet_start = quiet_start
        self.quiet_end = quiet_end
        self._user_preferences: dict[str, dict[str, bool]] = {}

    def add_user(self, user: str) -> None:
        """Add a new user with default channel preferences (email enabled, sms/push disabled)."""
        self._user_preferences[user] = {
            "email": True,
            "sms": False,
            "push": False,
        }

    def set_channel(self, user: str, channel: str, enabled: bool) -> None:
        """Enable or disable a specific delivery channel for a user."""
        if user not in self._user_preferences:
            self.add_user(user)
        if channel in self.CHANNELS:
            self._user_preferences[user][channel] = enabled

    def _is_quiet_hour(self, current_time: time) -> bool:
        """Determine if a given time falls within the configured quiet hours."""
        if self.quiet_start < self.quiet_end:
            # Quiet window within the same calendar day (e.g., 01:00 to 05:00)
            return self.quiet_start <= current_time < self.quiet_end
        elif self.quiet_start > self.quiet_end:
            # Quiet window spanning midnight (e.g., 22:00 to 07:00)
            return current_time >= self.quiet_start or current_time < self.quiet_end
        else:
            # quiet_start == quiet_end: either full day or no quiet window; typically treated as empty
            return False

    def send(self, user: str, message: str, at: datetime) -> list[str]:
        """Send a message; returns the channels it was delivered to, in CHANNELS order."""
        if user not in self._user_preferences:
            return []

        prefs = self._user_preferences[user]
        in_quiet_period = self._is_quiet_hour(at.time())
        delivered_channels: list[str] = []

        for channel in self.CHANNELS:
            if not prefs.get(channel, False):
                continue
            # During quiet hours, sms and push are muted; email is still delivered.
            if in_quiet_period and channel in ("sms", "push"):
                continue
            delivered_channels.append(channel)

        return delivered_channels
